/* Основные стили для 3D страницы с частицами */
body {
    margin: 0;
    padding: 0;
    overflow: hidden;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: #0a0a0f;
    color: #e0e0e0;
}

#particle-container {
    width: 100vw;
    height: 100vh;
    position: fixed;
    top: 0;
    left: 0;
}

// Основная логика Three.js страницы с частицами

// Ждем загрузки DOM перед инициализацией
document.addEventListener('DOMContentLoaded', init);

// Глобальные переменные для Three.js объектов
let scene, camera, renderer;
let particles;
let mouseX = 0;
let mouseY = 0;
const targetX = 0;
const targetY = 0;

// Инициализация сцены, камеры и рендерера
function init() {
    // Создание WebGLRenderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.shadowMap.enabled = true;
    document.getElementById('particle-container').appendChild(renderer.domElement);

    // Создание сцены
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0a0f);

    // Создание PerspectiveCamera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 50;

    // Создание системы частиц
    createParticles();

    // Слушатели событий
    window.addEventListener('resize', onWindowResize);
    document.addEventListener('mousemove', onMouseMove);

    // Запуск анимационного цикла
    animate();
}

// Создание геометрии частиц с BufferGeometry
function createParticles() {
    const particleCount = 5000;

    // BufferGeometry для эффективной отрисовки
    const geometry = new THREE.BufferGeometry();

    // Массивы для координат, размеров и цветов
    const positions = new Float32Array(particleCount * 3);
    const sizes = new Float32Array(particleCount * 1);
    const colors = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
        // Случайные координаты в 3D пространстве
        positions[i * 3] = (Math.random() - 0.5) * 100; // x
        positions[i * 3 + 1] = (Math.random() - 0.5) * 100; // y
        positions[i * 3 + 2] = (Math.random() - 0.5) * 100; // z

        // Случайный размер частицы
        sizes[i] = Math.random() * 2 + 0.5; // от 0.5 до 2.5

        // Цвет (синий-циановый градиент)
        colors[i * 3] = 0.5 + Math.random() * 0.5; // R
        colors[i * 3 + 1] = 0.7 + Math.random() * 0.3; // G
        colors[i * 3 + 2] = 1.0; // B
    }

    // Устанавливаем атрибуты в геометрию
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    // PointsMaterial с эффектом свечения и прозрачности
    const material = new THREE.PointsMaterial({
        size: 0.5,
        sizeAttenuation: true,
        vertexColors: true,
        transparent: true,
        opacity: 0.9,
        blending: THREE.AdditiveBlending,
        depthWrite: false
    });

    // Создание системы частиц
    particles = new THREE.Points(geometry, material);
    scene.add(particles);
}

// Анимационный цикл для вращения и пульсации частиц
function animate() {
    requestAnimationFrame(animate);

    // Плавное перемещение камеры за мышью (параллакс-эффект)
    camera.position.x += (targetX - camera.position.x) * 0.05;
    camera.position.y += (targetY - camera.position.y) * 0.05;
    camera.lookAt(scene.position);

    // Вращение системы частиц
    particles.rotation.x += 0.001;
    particles.rotation.y += 0.001;

    // Пульсация размеров частиц
    const sizes = particles.geometry.attributes.size;
    for (let i = 0; i < sizes.count; i++) {
        sizes.array[i] = Math.random() * 2 + 0.5 * (1 + Math.sin(Date.now() / 100 + i));
    }
    sizes.needsUpdate = true;

    // Рендеринг сцены
    renderer.render(scene, camera);
}

// Обработчик изменения размера окна
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Обработчик движения мыши для интерактивности
function onMouseMove(event) {
    // Нормализация координат мыши (-1 to 1)
    mouseX = (event.clientX / window.innerWidth) * 2 - 1;
    mouseY = -(event.clientY / window.innerHeight) * 2 + 1;

    // Сохраняем целевые координаты для плавного перемещения
    targetX = mouseX * 20;
    targetY = mouseY * 20;
}

