/* ===== Базовые переменные и сброс ===== */
:root {
  --bg: #0f1220;
  --bg-soft: #171b2e;
  --surface: #1e2336;
  --surface-2: #262c44;
  --border: #2e3552;
  --text: #e8ebf5;
  --text-dim: #9aa3c0;
  --primary: #6c8cff;
  --primary-strong: #4f6ef0;
  --danger: #ff5d6c;
  --success: #34d399;
  --radius: 14px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  --transition: 0.18s ease;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
  background: radial-gradient(1200px 600px at 80% -10%, #1b2140 0%, var(--bg) 55%);
  color: var(--text);
  min-height: 100vh;
  line-height: 1.45;
}

/* ===== Каркас приложения ===== */
.app {
  max-width: 820px;
  margin: 0 auto;
  padding: 28px 18px 60px;
}

.app__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 22px;
}

.app__title {
  margin: 0;
  font-size: 28px;
  letter-spacing: 0.3px;
}

.app__subtitle {
  margin: 4px 0 0;
  color: var(--text-dim);
  font-size: 14px;
}

.app__footer {
  margin-top: 26px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--text-dim);
  font-size: 13px;
  flex-wrap: wrap;
}

/* ===== Формы и поля ввода ===== */
.task-form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  display: grid;
  gap: 12px;
}

.task-form__row--inline {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.task-form__input,
.task-form__select {
  background: var(--bg-soft);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 10px;
  padding: 11px 13px;
  font-size: 15px;
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
  width: 100%;
}

.task-form__input:focus,
.task-form__select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(108, 140, 255, 0.18);
}

.task-form__input--date {
  width: auto;
}

.task-form__input--search {
  width: 200px;
}

.task-form__input--icon {
  width: 70px;
  text-align: center;
}

/* ===== Кнопки ===== */
.btn {
  border: none;
  border-radius: 10px;
  padding: 11px 16px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: transform var(--transition), background var(--transition), opacity var(--transition);
  color: #fff;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px);
}

.btn--primary {
  background: linear-gradient(180deg, var(--primary), var(--primary-strong));
}

.btn--primary:hover {
  opacity: 0.92;
}

.btn--ghost {
  background: var(--surface-2);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn--ghost:hover {
  background: var(--border);
}

.btn--danger {
  background: var(--danger);
}

.btn--danger:hover {
  opacity: 0.9;
}

.btn--small {
  padding: 8px 12px;
  font-size: 13px;
}

/* ===== Панель инструментов ===== */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 20px 0 14px;
  flex-wrap: wrap;
}

.filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 13px;
  cursor: pointer;
  transition: all var(--transition);
  user-select: none;
}

.chip:hover {
  color: var(--text);
}

.chip.is-active {
  color: #fff;
  border-color: transparent;
  background: var(--surface-2);
  box-shadow: inset 0 0 0 1px var(--primary);
}

.chip__dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.toolbar__right {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

/* ===== Список задач ===== */
.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
}

.task {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid var(--cat-color, var(--primary));
  border-radius: 12px;
  padding: 14px 16px;
  animation: pop 0.22s ease;
  transition: background var(--transition), opacity var(--transition);
}

@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.task:hover {
  background: var(--surface-2);
}

.task.is-done {
  opacity: 0.6;
}

.task.is-done .task__title {
  text-decoration: line-through;
  color: var(--text-dim);
}

.task__check {
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 2px solid var(--border);
  background: var(--bg-soft);
  cursor: pointer;
  flex-shrink: 0;
  margin-top: 2px;
  position: relative;
  transition: all var(--transition);
}

.task__check:checked {
  background: var(--success);
  border-color: var(--success);
}

.task__check:checked::after {
  content: "✓";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #06281c;
  font-size: 14px;
  font-weight: 800;
}

.task__body {
  flex: 1;
  min-width: 0;
}

.task__top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.task__title {
  font-size: 16px;
  font-weight: 600;
  word-break: break-word;
}

.task__badge {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--cat-color, var(--primary));
  color: #0c1020;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.task__prio {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--text-dim);
}

.task__prio--high {
  color: var(--danger);
  border-color: var(--danger);
}

.task__prio--medium {
  color: #f5c451;
  border-color: #f5c451;
}

.task__prio--low {
  color: var(--success);
  border-color: var(--success);
}

.task__desc {
  margin: 6px 0 0;
  color: var(--text-dim);
  font-size: 14px;
  word-break: break-word;
}

.task__meta {
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-dim);
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.task__due.is-overdue {
  color: var(--danger);
  font-weight: 600;
}

.task__actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
}

.icon-btn {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-dim);
  border-radius: 8px;
  width: 32px;
  height: 32px;
  cursor: pointer;
  font-size: 14px;
  transition: all var(--transition);
}

.icon-btn:hover {
  color: var(--text);
  background: var(--bg-soft);
}

.icon-btn--danger:hover {
  color: var(--danger);
  border-color: var(--danger);
}

/* ===== Пустое состояние ===== */
.empty-state {
  text-align: center;
  color: var(--text-dim);
  padding: 40px 0;
  font-size: 15px;
}

/* ===== Модальные окна ===== */
.modal {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  z-index: 50;
  padding: 16px;
}

.modal[hidden] {
  display: none;
}

.modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(5, 7, 15, 0.66);
  backdrop-filter: blur(2px);
}

.modal__dialog {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  width: min(520px, 100%);
  box-shadow: var(--shadow);
  animation: pop 0.2s ease;
}

.modal__title {
  margin: 0 0 16px;
  font-size: 20px;
}

.modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.field__label {
  font-size: 13px;
  color: var(--text-dim);
}

.field-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.field-row .field {
  flex: 1;
  min-width: 130px;
}

/* ===== Управление категориями ===== */
.cat-list {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: grid;
  gap: 8px;
  max-height: 240px;
  overflow-y: auto;
}

.cat-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 12px;
}

.cat-item__dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
}

.cat-item__name {
  flex: 1;
  font-size: 14px;
}

.cat-add {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.cat-color {
  width: 42px;
  height: 42px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg-soft);
  cursor: pointer;
  padding: 2px;
}

/* ===== Адаптив ===== */
@media (max-width: 560px) {
  .task-form__input--search {
    width: 100%;
  }
  .toolbar__right {
    width: 100%;
  }
  .toolbar__right .task-form__input--search,
  .toolbar__right .task-form__select {
    flex: 1;
  }
  .field-row {
    flex-direction: column;
  }
}

