    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function formatDate(iso) {
    if (!iso) return "";
    const d = new Date(iso + "T00:00:00");
    if (isNaN(d)) return "";
    return d.toLocaleDateString("ru-RU", { day: "2-digit", month: "2-digit", year: "numeric" });
  }

  function isOverdue(iso, done) {
    if (!iso || done) return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(iso + "T00:00:00");
    return due < today;
  }

  /* ---------- Работа с хранилищем ---------- */
  function loadState() {
    try {
      const rawTasks = localStorage.getItem(STORAGE_KEYS.tasks);
      const rawCats = localStorage.getItem(STORAGE_KEYS.categories);
      state.tasks = rawTasks ? JSON.parse(rawTasks) : [];
      state.categories = rawCats ? JSON.parse(rawCats) : DEFAULT_CATEGORIES.slice();
    } catch (err) {
      console.error("Ошибка загрузки из LocalStorage:", err);
      state.tasks = [];
      state.categories = DEFAULT_CATEGORIES.slice();
    }
    // Если категорий нет вовсе — ставим дефолтные
    if (!Array.isArray(state.categories) || state.categories.length === 0) {
      state.categories = DEFAULT_CATEGORIES.slice();
    }
  }

  function saveTasks() {
    try {
      localStorage.setItem(STORAGE_KEYS.tasks, JSON.stringify(state.tasks));
    } catch (err) {
      console.error("Ошибка сохранения задач:", err);
    }
  }

  function saveCategories() {
    try {
      localStorage.setItem(STORAGE_KEYS.categories, JSON.stringify(state.categories));
    } catch (err) {
      console.error("Ошибка сохранения категорий:", err);
    }
  }

  /* ---------- Поиск категории ---------- */
  function getCategory(id) {
    return state.categories.find((c) => c.id === id) || state.categories[0];
  }

  /* ---------- CRUD: задачи ---------- */
  function addTask(data) {
    const task = {
      id: uid(),
      title: data.title.trim(),
      desc: (data.desc || "").trim(),
      category: data.category,
      priority: data.priority || "medium",
      due: data.due || "",
      done: false,
      createdAt: Date.now(),
    };
    state.tasks.unshift(task);
    saveTasks();
    render();
  }

  function updateTask(id, patch) {
    const t = state.tasks.find((x) => x.id === id);
    if (!t) return;
    Object.assign(t, patch);
    saveTasks();
    render();
  }

  function deleteTask(id) {
    state.tasks = state.tasks.filter((x) => x.id !== id);
    saveTasks();
    render();
  }

  function toggleDone(id) {
    const t = state.tasks.find((x) => x.id === id);
    if (!t) return;
    t.done = !t.done;
    saveTasks();
    render();
  }

  /* ---------- CRUD: категории ---------- */
  function addCategory(data) {
    const cat = {
      id: uid(),
      name: data.name.trim(),
      icon: (data.icon || "🏷️").trim() || "🏷️",
      color: data.color || "#6c8cff",
    };
    state.categories.push(cat);
    saveCategories();
    renderCategorySelects();
    renderCategoryFilters();
    renderCategoryList();
  }

  function deleteCategory(id) {
    // Нельзя удалить последнюю категорию
    if (state.categories.length <= 1) {
      alert("Должна остаться хотя бы одна категория.");
      return;
    }
    const fallback = state.categories.find((c) => c.id !== id);
    // Переносим задачи удаляемой категории в первую оставшуюся
    state.tasks.forEach((t) => {
      if (t.category === id) t.category = fallback.id;
    });
    state.categories = state.categories.filter((c) => c.id !== id);
    if (state.activeFilter === id) state.activeFilter = "all";
    saveCategories();
    saveTasks();
    render();
    renderCategorySelects();
    renderCategoryFilters();
    renderCategoryList();
  }

  /* ---------- Фильтрация и сортировка ---------- */
  function getVisibleTasks() {
    let list = state.tasks.slice();

    // Фильтр по категории
    if (state.activeFilter !== "all") {
      list = list.filter((t) => t.category === state.activeFilter);
    }

    // Поиск
    const q = state.search.trim().toLowerCase();
    if (q) {
      list = list.filter(
        (t) =>
          t.title.toLowerCase().includes(q) ||
          (t.desc || "").toLowerCase().includes(q)
      );
    }

    // Сортировка
    const prioRank = { high: 0, medium: 1, low: 2 };
    list.sort((a, b) => {
      switch (state.sort) {
        case "priority":
          return prioRank[a.priority] - prioRank[b.priority] || a.createdAt - b.createdAt;
        case "due":
          // Пустые сроки — в конец
          if (!a.due) return 1;
          if (!b.due) return -1;
          return a.due.localeCompare(b.due);
        case "title":
          return a.title.localeCompare(b.title, "ru");
        case "created":
        default:
          return b.createdAt - a.createdAt;
      }
    });

    return list;
  }

  /* ---------- Рендер: статистика ---------- */
  function renderStats() {
    const total = state.tasks.length;
    const done = state.tasks.filter((t) => t.done).length;
    const active = total - done;
    $("#stats").textContent = `Всего: ${total} · Активно: ${active} · Выполнено: ${done}`;
  }

  /* ---------- Рендер: выпадающие списки категорий ---------- */
  function renderCategorySelects() {
    const opts = state.categories
      .map((c) => `<option value="${c.id}">${escapeHtml(c.icon)} ${escapeHtml(c.name)}</option>`)
      .join("");
    const main = $("#taskCategory");
    const edit = $("#editTaskCategory");
    if (main) main.innerHTML = opts;
    if (edit) edit.innerHTML = opts;
  }

  /* ---------- Рендер: фильтры-чипы ---------- */
  function renderCategoryFilters() {
    const wrap = $("#categoryFilters");
    if (!wrap) return;
    const chips = [`<button type="button" class="chip ${state.activeFilter === "all" ? "is-active" : ""}" data-filter="all">📋 Все</button>`];
    state.categories.forEach((c) => {
      const active = state.activeFilter === c.id ? "is-active" : "";
      chips.push(
        `<button type="button" class="chip ${active}" data-filter="${c.id}">
          <span class="chip__dot" style="background:${c.color}"></span>${escapeHtml(c.icon)} ${escapeHtml(c.name)}
        </button>`
      );
    });
    wrap.innerHTML = chips.join("");
  }

  /* ---------- Рендер: список задач ---------- */
  function renderTasks() {
    const list = $("#taskList");
    const empty = $("#emptyState");
    if (!list) return;

    const visible = getVisibleTasks();
    list.innerHTML = "";

    if (visible.length === 0) {
      empty.hidden = false;
      empty.textContent = state.tasks.length === 0
        ? "Задач пока нет. Добавьте первую! ✨"
        : "Ничего не найдено по выбранным фильтрам.";
      return;
    }
    empty.hidden = true;

    visible.forEach((t) => {
      const cat = getCategory(t.category);
      const li = document.createElement("li");
      li.className = "task" + (t.done ? " is-done" : "");
      li.style.setProperty("--cat-color", cat.color);

      const prioLabel = { high: "Высокий", medium: "Средний", low: "Низкий" }[t.priority];
      const prioClass = "task__prio--" + t.priority;

      const dueHtml = t.due
        ? `<span class="task__due ${isOverdue(t.due, t.done) ? "is-overdue" : ""}">📅 ${formatDate(t.due)}${isOverdue(t.due, t.done) ? " (просрочено)" : ""}</span>`
        : "";

      li.innerHTML = `
        <input type="checkbox" class="task__check" ${t.done ? "checked" : ""} aria-label="Отметить выполненной" />
        <div class="task__body">
          <div class="task__top">
            <span class="task__title">${escapeHtml(t.title)}</span>
            <span class="task__badge">${escapeHtml(cat.icon)} ${escapeHtml(cat.name)}</span>
            <span class="task__prio ${prioClass}">${prioLabel}</span>
          </div>
          ${t.desc ? `<p class="task__desc">${escapeHtml(t.desc)}</p>` : ""}
          <div class="task__meta">
            ${dueHtml}
            <span>🕓 ${new Date(t.createdAt).toLocaleDateString("ru-RU")}</span>
          </div>
        </div>
        <div class="task__actions">
          <button type="button" class="icon-btn" data-edit="${t.id}" title="Редактировать">✏️</button>
          <button type="button" class="icon-btn icon-btn--danger" data-del="${t.id}" title="Удалить">🗑️</button>
        </div>
      `;

      // Обработчики
      li.querySelector(".task__check").addEventListener("change", () => toggleDone(t.id));
      li.querySelector("[data-edit]").addEventListener("click", () => openEditModal(t.id));
      li.querySelector("[data-del]").addEventListener("click", () => {
        if (confirm("Удалить задачу «" + t.title + "»?")) deleteTask(t.id);
      });

      list.appendChild(li);
    });
  }

  /* ---------- Рендер: модалка категорий ---------- */
  function renderCategoryList() {
    const ul = $("#catList");
    if (!ul) return;
    ul.innerHTML = state.categories
      .map(
        (c) => `
        <li class="cat-item">
          <span class="cat-item__dot" style="background:${c.color}"></span>
          <span class="cat-item__name">${escapeHtml(c.icon)} ${escapeHtml(c.name)}</span>
          <button type="button" class="icon-btn icon-btn--danger" data-catdel="${c.id}" title="Удалить">🗑️</button>
        </li>`
      )
      .join("");
    $$("[data-catdel]", ul).forEach((btn) => {
      btn.addEventListener("click", () => {
        if (confirm("Удалить категорию? Задачи будут перенесены в другую.")) {
          deleteCategory(btn.getAttribute("data-catdel"));
        }
      });
    });
  }

  /* ---------- Главный рендер ---------- */
  function render() {
    renderStats();
    renderCategoryFilters();
    renderTasks();
  }

  /* ---------- Модальные окна ---------- */
  function openModal(id) {
    $(id).hidden = false;
  }
  function closeModal(id) {
    $(id).hidden = true;
  }

  let editingId = null;
  function openEditModal(id) {
    const t = state.tasks.find((x) => x.id === id);
    if (!t) return;
    editingId = id;
    $("#editTaskTitle").value = t.title;
    $("#editTaskDesc").value = t.desc || "";
    $("#editTaskCategory").value = t.category;
    $("#editTaskPriority").value = t.priority;
    $("#editTaskDue").value = t.due || "";
    openModal("#editModal");
  }

  /* ---------- Привязка событий ---------- */
  function bindEvents() {
    // Добавление задачи
    $("#taskForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const title = $("#taskTitle").value.trim();
      if (!title) return;
      addTask({
        title,
        desc: $("#taskDesc").value,
        category: $("#taskCategory").value,
        priority: $("#taskPriority").value,
        due: $("#taskDue").value,
      });
      e.target.reset();
      $("#taskPriority").value = "medium";
      $("#taskTitle").focus();
    });

    // Фильтры категорий (делегирование)
    $("#categoryFilters").addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (!chip) return;
      state.activeFilter = chip.getAttribute("data-filter");
      renderCategoryFilters();
      renderTasks();
    });

    // Поиск
    $("#searchInput").addEventListener("input", (e) => {
      state.search = e.target.value;
      renderTasks();
    });

    // Сортировка
    $("#sortSelect").addEventListener("change", (e) => {
      state.sort = e.target.value;
      renderTasks();
    });

    // Очистить выполненные
    $("#clearDoneBtn").addEventListener("click", () => {
      const done = state.tasks.filter((t) => t.done).length;
      if (done === 0) return;
      if (confirm(`Удалить ${done} выполненных задач?`)) {
        state.tasks = state.tasks.filter((t) => !t.done);
        saveTasks();
        render();
      }
    });

    // Модалка редактирования
    $("#editForm").addEventListener("submit", (e) => {
      e.preventDefault();
      if (!editingId) return;
      const title = $("#editTaskTitle").value.trim();
      if (!title) return;
      updateTask(editingId, {
        title,
        desc: $("#editTaskDesc").value,
        category: $("#editTaskCategory").value,
        priority: $("#editTaskPriority").value,
        due: $("#editTaskDue").value,
      });
      closeModal("#editModal");
    });

    // Закрытие модалок
    $$("[data-close]").forEach((el) => {
      el.addEventListener("click", () => {
        const which = el.getAttribute("data-close");
        closeModal(which === "edit" ? "#editModal" : "#catModal");
      });
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        closeModal("#editModal");
        closeModal("#catModal");
      }
    });

    // Кнопка управления категориями
    $("#manageCategoriesBtn").addEventListener("click", () => {
      renderCategoryList();
      openModal("#catModal");
    });

    // Добавление категории
    $("#catForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const name = $("#catName").value.trim();
      if (!name) return;
      addCategory({
        name,
        icon: $("#catIcon").value,
        color: $("#catColor").value,
      });
      e.target.reset();
      $("#catIcon").value = "🏷️";
      $("#catColor").value = "#6c8cff";
    });
  }

  /* ---------- Инициализация ---------- */
  function init() {
    loadState();
    renderCategorySelects();
    renderCategoryFilters();
    renderCategoryList();
    bindEvents();
    render();
  }

  document.addEventListener("DOMContentLoaded", init);
})();

